8],[42.2584,2.37581],[42.2584,2.37574],[42.2585,2.37565],[42.2586,2.37556],[42.2587,2.37547],[42.2587,2.37544],[42.2587,2.37539],[42.2588,2.37533],[42.2589,2.37528],[42.2589,2.37523],[42.259,2.37515],[42.2591,2.37508],[42.2591,2.375],[42.2592,2.37496],[42.2592,2.37494],[42.2593,2.37493],[42.2593,2.37493],[42.2593,2.37492],[42.2594,2.37488],[42.2595,2.37485],[42.2595,2.37482],[42.2596,2.37476],[42.2597,2.3747],[42.2598,2.37467],[42.2598,2.37465],[42.2598,2.37464],[42.2598,2.3746],[42.2599,2.37457],[42.2599,2.37449],[42.2599,2.37445],[42.2599,2.37435],[42.26,2.37428],[42.26,2.3742],[42.26,2.37416],[42.26,2.37414],[42.2601,2.37407],[42.2601,2.37402],[42.2601,2.37398],[42.2601,2.37394],[42.2601,2.37391],[42.2602,2.37379],[42.2602,2.3737],[42.2602,2.37361],[42.2602,2.37347],[42.2602,2.37345],[42.2602,2.37343],[42.2603,2.37335],[42.2603,2.37333],[42.2603,2.37317],[42.2603,2.37312],[42.2604,2.37308],[42.2604,2.37303],[42.2604,2.373],[42.2605,2.37296],[42.2606,2.37292],[42.2606,2.37287],[42.2607,2.3728],[42.2608,2.37277],[42.2608,2.37273],[42.2609,2.37269],[42.261,2.37263],[42.2611,2.37258],[42.2612,2.37252],[42.2612,2.3725],[42.2613,2.37241],[42.2613,2.37235],[42.2613,2.37235],[42.2612,2.3723]],"point_count":1365,"measured_km":8.381704399970697,"max_gap_km":0.023193126808828575,"closure_gap_km":5.4110236738332125,"start":[42.2367,2.4291],"end":[42.2612,2.3723]}]$routes$::jsonb;
  v_spec jsonb;
  v_route record;
  v_coords jsonb;
  v_points jsonb;
  v_count integer;
  v_length_km double precision;
  v_max_gap_km double precision;
  v_center_gap_km double precision;
  v_closure_gap_km double precision;
  v_invalid integer;
  v_start_gap_m double precision;
  v_end_gap_m double precision;
begin
  for v_spec in select value from jsonb_array_elements(v_specs)
  loop
    v_coords := v_spec->'coords';

    select h.id,h.latitude,h.longitude,h.distance_km,t.status,t.geometry_source_url
      into v_route
      from public.hiking_routes h
      join public.hiking_route_tracks t on t.route_id=h.id
      where h.id=v_spec->>'id'
        and h.source='openstreetmap'
        and h.name=v_spec->>'name'
        and coalesce(h.route_ref,'')=v_spec->>'ref'
        and h.route_type=v_spec->>'route_type'
        and h.official_url in (v_spec->>'legacy_url',v_spec->>'official_url')
        and (
          abs(h.distance_km-(v_spec->>'catalog_distance')::numeric)<0.01
          or (t.status='ready' and abs(h.distance_km-(v_spec->>'measured_km')::numeric)<0.02)
        )
        and exists (
          select 1 from public.hiking_route_regions r
          where r.route_id=h.id and r.published
        );

    if not found then
      raise exception 'Official route identity or published region changed: %',v_spec->>'id';
    end if;
    if v_route.status='ready' then
      if v_route.geometry_source_url=v_spec->>'gpx_url' then
        continue;
      end if;
      raise exception 'Route % became ready from an unexpected source: %',
        v_route.id,v_route.geometry_source_url;
    end if;
    if v_route.status<>'missing' then
      raise exception 'Official route status changed for %: %',v_route.id,v_route.status;
    end if;

    with points as (
      select ordinality idx,(point->>0)::double precision lat,
        (point->>1)::double precision lon
      from jsonb_array_elements(v_coords) with ordinality as p(point,ordinality)
    ), steps as (
      select *,lag(lat) over(order by idx) prev_lat,
        lag(lon) over(order by idx) prev_lon
      from points
    ), distances as (
      select case when prev_lat is null then 0 else
        ST_DistanceSphere(ST_MakePoint(lon,lat),
          ST_MakePoint(prev_lon,prev_lat))/1000 end step_km,
        ST_DistanceSphere(ST_MakePoint(lon,lat),
          ST_MakePoint(v_route.longitude,v_route.latitude))/1000 center_km,
        (lat between 27 and 45 and lon between -19 and 5) valid
      from steps
    )
    select count(*),coalesce(sum(step_km),0),coalesce(max(step_km),0),
      coalesce(min(center_km),999),count(*) filter(where not valid)
      into v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid
      from distances;

    select
      ST_DistanceSphere(
        ST_MakePoint((v_coords->0->>1)::double precision,(v_coords->0->>0)::double precision),
        ST_MakePoint((v_spec->'start'->>1)::double precision,(v_spec->'start'->>0)::double precision)
      ),
      ST_DistanceSphere(
        ST_MakePoint((v_coords->(v_count-1)->>1)::double precision,(v_coords->(v_count-1)->>0)::double precision),
        ST_MakePoint((v_spec->'end'->>1)::double precision,(v_spec->'end'->>0)::double precision)
      ),
      ST_DistanceSphere(
        ST_MakePoint((v_coords->0->>1)::double precision,(v_coords->0->>0)::double precision),
        ST_MakePoint((v_coords->(v_count-1)->>1)::double precision,(v_coords->(v_count-1)->>0)::double precision)
      )/1000
      into v_start_gap_m,v_end_gap_m,v_closure_gap_km;

    if v_count<>(v_spec->>'point_count')::integer
      or v_invalid>0
      or abs(v_length_km-(v_spec->>'measured_km')::double precision)>0.01
      or abs(v_length_km-(v_spec->>'official_distance')::double precision)>
        (v_spec->>'max_distance_delta')::double precision
      or v_max_gap_km>(v_spec->>'max_gap_limit')::double precision
      or v_center_gap_km>(v_spec->>'max_center_gap')::double precision
      or v_start_gap_m>2
      or v_end_gap_m>2
      or (v_spec->>'route_type'='Circular' and
          v_closure_gap_km>(v_spec->>'max_closure_gap')::double precision) then
      raise exception 'Official GPX validation failed for %: points %, length %, gap %, center %, closure %, start %, end %, invalid %',
        v_route.id,v_count,v_length_km,v_max_gap_km,v_center_gap_km,
        v_closure_gap_km,v_start_gap_m,v_end_gap_m,v_invalid;
    end if;

    select jsonb_agg(jsonb_build_object(
      'lat',(point->>0)::double precision,
      'lon',(point->>1)::double precision
    ) order by ordinality)
      into v_points
      from jsonb_array_elements(v_coords)
        with ordinality as p(point,ordinality);

    insert into public.hiking_route_tracks
      (route_id,status,segments,checked_at,continuity_checked,
       geometry_source,geometry_source_url,official)
    values (
      v_route.id,'ready',jsonb_build_array(v_points),now(),true,
      v_spec->>'source_name',v_spec->>'gpx_url',true
    )
    on conflict(route_id) do update set
      status=excluded.status,
      segments=excluded.segments,
      checked_at=excluded.checked_at,
      continuity_checked=true,
      geometry_source=excluded.geometry_source,
      geometry_source_url=excluded.geometry_source_url,
      official=true;

    update public.hiking_routes
      set trace_available=true,
          published=true,
          official_url=v_spec->>'official_url',
          distance_km=round(v_length_km::numeric,2),
          duration_minutes=(v_spec->>'official_duration_minutes')::integer,
          description=v_spec->>'official_description'
      where id=v_route.id;
  end loop;
end
$curate$;

